INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q937774', 'Helladic period', 'Helladic chronology is a relative dating system used in archaeology and art history. It complements the Minoan chronology scheme devised by Sir Arthur Evans for the categorisation of Bronze Age artefacts from the Minoan civilization within a historical framework.', -3000, NULL, NULL, -1100, NULL, NULL, 'year', '3000 BCE – 1100 BCE', 68, 'https://en.wikipedia.org/wiki/Helladic_chronology'),
  ('Q31900', 'Battle of Marathon', 'The Battle of Marathon took place in 490 BCE during the first Persian invasion of Greece. It was fought between the citizens of Athens, aided by Plataea, against a Persian force commanded by Datis and Artaphernes.', -490, 9, 12, NULL, NULL, NULL, 'day', '12 September 490 BCE', 82, 'https://en.wikipedia.org/wiki/Battle_of_Marathon'),
  ('Q131969', 'Battle of Thermopylae', 'The Battle of Thermopylae was fought in 480 BC at Thermopylae between the Achaemenid Persian Empire under Xerxes and an alliance of Greek city-states led by Sparta under Leonidas I. Lasting over the course of three days, it was one of the most prominent battles of both the second Persian invasion of Greece and the wider Greco-Persian Wars. The engagement occurred simultaneously with the naval Battle of Artemisium: between July and September during 480 BC. The second Persian invasion under Xerxes was a delayed response to the failure of the first Persian invasion, which had been initiated by…', -480, 8, 11, NULL, NULL, NULL, 'day', '11 August 480 BCE', 84, 'https://en.wikipedia.org/wiki/Battle_of_Thermopylae'),
  ('Q178850', 'Battle of Salamis', 'The Battle of Salamis ( SAL-ə-miss) was a naval battle fought in 480 BC, between an alliance of Greek city-states under Themistocles, and the Achaemenid Empire under King Xerxes. It resulted in a victory for the outnumbered Greeks.', -480, 9, 29, NULL, NULL, NULL, 'day', '29 September 480 BCE', 80, 'https://en.wikipedia.org/wiki/Battle_of_Salamis'),
  ('Q747679', 'Battle of Artemisium', 'The Battle of Artemisium or Artemision was a series of naval engagements over three days during the second Persian invasion of Greece. The battle took place simultaneously with the land battle at Thermopylae, in August or September 480 BC, off the coast of Euboea and was fought between an alliance of Greek city-states, including Sparta, Athens, Corinth and others, and the Persian Empire of Xerxes I. The Persian invasion was a delayed response to the defeat of the first Persian invasion of Greece, which had been ended by the Athenian victory at the Battle of Marathon.', -480, NULL, NULL, NULL, NULL, NULL, 'year', '480 BCE', 67, 'https://en.wikipedia.org/wiki/Battle_of_Artemisium'),
  ('Q1122337', 'Second Persian invasion of Greece', 'The second Persian invasion of Greece (480–479 BC) occurred during the Greco-Persian Wars, as King Xerxes I of Persia sought to conquer all of Greece. The invasion was a direct, if delayed, response to the defeat of the first Persian invasion of Greece (492–490 BC) at the Battle of Marathon, which ended Darius I''s attempts to subjugate Greece.', -480, NULL, NULL, -479, NULL, NULL, 'year', '480 BCE – 479 BCE', 61, 'https://en.wikipedia.org/wiki/Second_Persian_invasion_of_Greece'),
  ('Q204636', 'Battle of Plataea', 'The Battle of Plataea was the final land battle during the second Persian invasion of Greece. It took place in August 479 BC near the city of Plataea in Boeotia, and was fought between an Achaemenid army led by Mardonius (allied with Boeotia, Thessaly, and Macedon) and the Spartan-led Hellenic alliance including Athens, Corinth, Tegea, Megara and other city-states.', -479, 8, 27, NULL, NULL, NULL, 'day', '27 August 479 BCE', 75, 'https://en.wikipedia.org/wiki/Battle_of_Plataea'),
  ('Q233553', 'Second Sacred War', 'The Second Sacred War was the Spartan defeat of the Phocians at Delphi and the restoration of Delphian self-government.', -449, NULL, NULL, -448, NULL, NULL, 'year', '449 BCE – 448 BCE', 56, 'https://en.wikipedia.org/wiki/Second_Sacred_War'),
  ('Q1356189', 'Battle of Potidaea', 'The Battle of Potidaea was fought in 432 BC between Athens and a combined army from Corinth and Potidaea, along with their various allies. Along with the Battle of Sybota, it was one of the catalysts for the Peloponnesian War.', -432, NULL, NULL, NULL, NULL, NULL, 'year', '432 BCE', 59, 'https://en.wikipedia.org/wiki/Battle_of_Potidaea'),
  ('Q758173', 'Plague of Athens', 'The Plague of Athens (Ancient Greek: Λοιμὸς τῶν Ἀθηνῶν, Loimos tôn Athênôn) was an epidemic that devastated the city-state of Athens in ancient Greece during the second year (430 BC) of the Peloponnesian War when an Athenian victory still seemed within reach. The plague killed an estimated 75,000 to 100,000 people, around 25% of the population, and is believed to have entered Athens through Piraeus, the city''s port and sole source of food and supplies.', -430, NULL, NULL, -426, NULL, NULL, 'year', '430 BCE – 426 BCE', 65, 'https://en.wikipedia.org/wiki/Plague_of_Athens'),
  ('Q176416', 'Battle of Sphacteria', 'The Battle of Sphacteria was a land battle of the Peloponnesian War, fought in 425 BC between Athens and Sparta. Following the Battle of Pylos and subsequent peace negotiations, which failed, a number of Spartans were stranded on the island of Sphacteria.', -425, NULL, NULL, NULL, NULL, NULL, 'year', '425 BCE', 58, 'https://en.wikipedia.org/wiki/Battle_of_Sphacteria'),
  ('Q670128', 'Battle of Pylos', 'The Battle of Pylos, fought at sea and land, took place in 425 BC during the Peloponnesian War at the peninsula of Pylos, on the present-day Bay of Navarino in Messenia, and was an Athenian victory over Sparta. An Athenian fleet had been driven ashore at Pylos by a storm, and, at the instigation of Demosthenes, the Athenian soldiers fortified the peninsula, and a small force was left there when the fleet departed again.', -425, NULL, NULL, NULL, NULL, NULL, 'year', '425 BCE', 57, 'https://en.wikipedia.org/wiki/Battle_of_Pylos'),
  ('Q1424844', 'Battle of Delium', 'The Battle of Delium (or Delion, a city in Boeotia) took place in 424 BC, during the Peloponnesian War. It was fought between the Athenians and the Boeotians, who were allies of the Spartans, and ended with the siege of Delium in the following weeks.', -424, NULL, NULL, NULL, NULL, NULL, 'year', '424 BCE', 59, 'https://en.wikipedia.org/wiki/Battle_of_Delium'),
  ('Q637544', 'Battle of Amphipolis', 'The Battle of Amphipolis was fought in 422 BC during the Peloponnesian War between Athens and Sparta. It was the culmination of events that began in 424 BC with the capture of Amphipolis by the Spartans.', -422, NULL, NULL, NULL, NULL, NULL, 'year', '422 BCE', 58, 'https://en.wikipedia.org/wiki/Battle_of_Amphipolis'),
  ('Q1362053', 'Battle of Mantinea', 'The first Battle of Mantinea was fought in 418 BC during the Peloponnesian War. In this battle, Sparta and its Peloponnesian allies defeated an allied army of Argos, Athens, Mantinea and several others.', -418, NULL, NULL, NULL, NULL, NULL, 'year', '418 BCE', 57, 'https://en.wikipedia.org/wiki/Battle_of_Mantinea_(418_BC)'),
  ('Q461599', 'Battle of Leuctra', 'The Battle of Leuctra (Ancient Greek: Λεῦκτρα, Ancient Greek: [lêu̯k.tra]) was fought on 6 July 371 BC between the Boeotians led by the Thebans, and the Spartans along with their allies. The battle occurred in the context of the King''s Peace, or Peace of Antalcidas, which had ended the Corinthian War in 386 BC. The Peace was formally renewed in 375 BC, but a disagreement between the Spartans and the Thebans over the protocol for renewing the Peace again in 371 led directly to the battle, which took place in the vicinity of Leuctra, a village in Boeotia in the territory of Thespiae.', -371, 7, 6, NULL, NULL, NULL, 'day', '6 July 371 BCE', 71, 'https://en.wikipedia.org/wiki/Battle_of_Leuctra'),
  ('Q233399', 'Battle of Mantinea', 'The Battle of Mantinea was fought on 4 July 362 BC between the Thebans, led by Epaminondas and supported by the Arcadians, Argives, Messenians, Thessalians, Euboeans and the Boeotian league against the Spartans, Eleans, Athenians, and Mantineans. The battle was to determine which of the two alliances would dominate Greece.', -362, 7, 4, NULL, NULL, NULL, 'day', '4 July 362 BCE', 61, 'https://en.wikipedia.org/wiki/Battle_of_Mantinea_(362_BC)'),
  ('Q200716', 'Battle of Chaeronea', 'The Battle of Chaeronea was fought in 338 BC, near the city of Chaeronea in Boeotia, between Macedonia under Philip II and an alliance of Greek city-states led by Athens and Thebes. The battle was the culmination of Philip''s final campaigns in 339–338 BC and resulted in a decisive victory for the Macedonians and their allies.', -338, 8, NULL, NULL, NULL, NULL, 'month', 'August 338 BCE', 75, 'https://en.wikipedia.org/wiki/Battle_of_Chaeronea_(338_BC)'),
  ('Q28365', 'Lamian War', 'The Lamian War or the Hellenic War (323–322 BC), was an unsuccessful attempt by Athens and a large coalition of Greek states to end the hegemony of Macedonia over Greece just after the death of Alexander the Great. It was the last time Athens played a significant role as an independent power.', -323, NULL, NULL, -322, NULL, NULL, 'year', '323 BCE – 322 BCE', 68, 'https://en.wikipedia.org/wiki/Lamian_War'),
  ('Q1076902', 'Chremonidean War', 'The Chremonidean War (Ancient Greek: Χρεμωνίδειος Πόλεμος) (267–261 BC) was fought by a coalition of Greek city-states and Ptolemaic Egypt against Antigonid Macedonia. It ended in a Macedonian victory that confirmed Antigonid control over Greece.', -267, NULL, NULL, -261, NULL, NULL, 'year', '267 BCE – 261 BCE', 61, 'https://en.wikipedia.org/wiki/Chremonidean_War'),
  ('Q1474893', 'Cleomenean War', 'The Cleomenean War (229/228–222 BC) was fought between Sparta and the Achaean League for the control of the Peloponnese. Under the leadership of king Cleomenes III, Sparta initially had the upper hand, which forced the Achaean League to call for help the Macedonian king Antigonos Doson, who decisively defeated Cleomenes in the battle of Sellasia in 222.', -229, NULL, NULL, -222, NULL, NULL, 'year', '229 BCE – 222 BCE', 60, 'https://en.wikipedia.org/wiki/Cleomenean_War'),
  ('Q204343', 'Battle of Sellasia', 'The Battle of Sellasia took place during the summer of 222 BC between Macedon and the Achaean League, led by Antigonus III Doson, and Sparta under the command of King Cleomenes III. The battle was fought at Sellasia, on the northern frontier of Laconia and ended in a Macedonian-Achaean victory. In 229 BC, Cleomenes initiated hostilities against the Achaean League, the dominant power of the Peloponnese.', -222, NULL, NULL, NULL, NULL, NULL, 'year', '222 BCE', 61, 'https://en.wikipedia.org/wiki/Battle_of_Sellasia'),
  ('Q75665', 'Second Macedonian War', 'The Second Macedonian War (200–197 BC) was fought between Macedon, led by Philip V of Macedon, and Rome, allied with Pergamon, Rhodes, Athens, Athamania, Dardania, Illyria and since 199 BC, the Aetolian League. Philip V and the king of the Seleucid Empire Antiochus the Great had previously made a pact against the Ptolemaic kingdom (after the death of Ptolemy IV).', -200, NULL, NULL, -197, NULL, NULL, 'year', '200 BCE – 197 BCE', 69, 'https://en.wikipedia.org/wiki/Second_Macedonian_War'),
  ('Q391087', 'Battle of Cynoscephalae', 'The Battle of Cynoscephalae (Greek: Μάχη τῶν Κυνὸς Κεφαλῶν) was an encounter battle fought in Thessaly in June 197 BC between the Roman-Aetolian army, led by Titus Quinctius Flamininus, and Antigonid Macedon, led by Philip V, during the Second Macedonian War. It was a decisive Roman victory and marked the end of the conflict.', -197, NULL, NULL, NULL, NULL, NULL, 'year', '197 BCE', 69, 'https://en.wikipedia.org/wiki/Battle_of_Cynoscephalae'),
  ('Q486831', 'Roman–Seleucid War', 'The Roman–Seleucid war (192–188 BC), also called the Aetolian war, Antiochene war, Syrian war, and Syrian-Aetolian war was a military conflict between two coalitions, one led by the Roman Republic and the other led by the Seleucid king Antiochus III. The fighting took place in modern-day southern mainland Greece, the Aegean Sea, and Asia Minor. The war was the consequence of a "cold war" between both powers, which had started in 196 BC. In this period, the Romans and the Seleucids attempted to settle spheres of influence by forging alliances with the small Greek city-states.', -192, NULL, NULL, -188, NULL, NULL, 'year', '192 BCE – 188 BCE', 68, 'https://en.wikipedia.org/wiki/Roman%E2%80%93Seleucid_war'),
  ('Q783058', 'Battle of Thermopylae', 'The Battle of Thermopylae took place on 24 April 191 BC. It was fought as part of the Roman–Seleucid War, pitting forces of the Roman Republic led by the consul Manius Acilius Glabrio against a Seleucid-Aetolian army of Antiochus III the Great. When the main bodies of the armies initially clashed at the Thermopylae pass, the Seleucids managed to hold their ground, repulsing multiple Roman assaults.', -191, NULL, NULL, NULL, NULL, NULL, 'year', '191 BCE', 61, 'https://en.wikipedia.org/wiki/Battle_of_Thermopylae_(191_BC)'),
  ('Q504739', 'Battle of Pydna', 'The Battle of Pydna took place in 168 BC between Rome and Macedon during the Third Macedonian War. The battle saw the further ascendancy of Rome in the Hellenistic world and the end of the Antigonid line of kings, whose power traced back to Alexander the Great''s Diadochi Antigonus Monophthalmus.', -168, 6, 22, NULL, NULL, NULL, 'day', '22 June 168 BCE', 68, 'https://en.wikipedia.org/wiki/Battle_of_Pydna'),
  ('Q587983', 'Battle of Corinth', 'The Battle of Corinth of 146 BC, also known as the Battle of Leucapetra or the Battle of Lefkopetra, was a decisive engagement fought between the Roman Republic and the Greek city-state of Corinth and its allies in the Achaean League. The battle marked the end of the Achaean War and the beginning of the period of Roman domination in Greek history, and is also notable for the complete destruction of Corinth by the Romans in its aftermath.', -146, NULL, NULL, NULL, NULL, NULL, 'year', '146 BCE', 61, 'https://en.wikipedia.org/wiki/Battle_of_Corinth_(146_BC)'),
  ('Q233352', 'Battle of Chaeronea', 'The Battle of Chaeronea was fought by the Roman forces of Lucius Cornelius Sulla and Mithridates'' general, Archelaus, near Chaeronea, in Boeotia, in 86 BC during the First Mithridatic War. The battle ended with a complete rout of the Pontic army and a decisive victory for the Romans.', -86, NULL, NULL, NULL, NULL, NULL, 'year', '86 BCE', 60, 'https://en.wikipedia.org/wiki/Battle_of_Chaeronea_(86_BC)'),
  ('Q203681', 'Battle of Pharsalus', 'The Battle of Pharsalus was the decisive battle of Caesar''s Civil War fought on 9 August 48 BC near Pharsalus in Central Greece. Julius Caesar and his allies formed up opposite the army of the Roman Republic under the command of Pompey.', -48, 8, 9, NULL, NULL, NULL, 'day', '9 August 48 BCE', 73, 'https://en.wikipedia.org/wiki/Battle_of_Pharsalus'),
  ('Q335330', 'Battle of Philippi', 'The Battle of Philippi was the final battle in the Liberators'' civil war between the forces of Mark Antony and Octavian (of the Second Triumvirate) and the leaders of the assassins of Julius Caesar, Brutus and Cassius, in 42 BC, at Philippi in Macedonia. The Second Triumvirate declared the civil war ostensibly to avenge Julius Caesar''s assassination in 44 BC, but the underlying cause was a long-brewing conflict between the Optimates and Populares.', -42, 10, 3, -42, 10, 23, 'day', '3 October 42 BCE – 23 October 42 BCE', 70, 'https://en.wikipedia.org/wiki/Battle_of_Philippi'),
  ('Q1348954', '365 Crete earthquake', 'The 365 Crete earthquake occurred at about sunrise on 21 July 365 in the Eastern Mediterranean, with an assumed epicentre near Crete. Geologists today estimate the undersea earthquake to have been a moment magnitude 8.5 or higher.', 365, 7, 21, NULL, NULL, NULL, 'day', '21 July 365', 61, 'https://en.wikipedia.org/wiki/365_Crete_earthquake'),
  ('Q1197995', 'Frankokratia', 'The Frankish Occupation, also known as the Latin Occupation (Λατινοκρατία, Latinokratía) and, for the Venetian domains, Venetian Occupation, were the collection of primarily French and Italian states, fiefs and colonies that were established by the Partitio terrarum imperii Romaniae on the territory of the partitioned Byzantine Empire following the Sack of Constantinople of 1204 during the Fourth Crusade. The terms Frankokratia and Latinokratia derive from the name "Franks", given by the Orthodox Greeks to the Western French and Italians who originated from territories that once belonged to…', 1204, NULL, NULL, 1453, NULL, NULL, 'year', '1204–1453', 67, 'https://en.wikipedia.org/wiki/Frankokratia'),
  ('Q939570', 'Battle of Maritsa', 'The Battle of Maritsa, also known as the Battle of Chernomen (Serbian: Marička bitka / Маричка битка; Turkish: Çirmen Muharebesi, İkinci Meriç Muharebesi; "Second Battle of Maritsa"), was fought on 26 September 1371 near the Maritsa River, close to the village of Chernomen (present-day Ormenio, Greece). The conflict pitted the Ottoman forces under Lala Şahin Pasha and Hacı İlbey against a coalition of Serbian lords, led by King Vukašin Mrnjavčević and his brother Despot Jovan Uglješa who sought to halt the Ottomans'' westward advance.', 1371, 9, 26, NULL, NULL, NULL, 'day', '26 September 1371', 69, 'https://en.wikipedia.org/wiki/Battle_of_Maritsa'),
  ('Q2426040', 'Siege of Thessalonica', 'The siege of Thessalonica between 1422 and 1430 saw the Ottoman Empire, under Sultan Murad II, capture the city of Thessalonica. Afterwards, the city remained in Ottoman hands for the next five centuries until it became part of the Kingdom of Greece in 1912.', 1422, 6, NULL, 1430, 3, 29, 'month', 'June 1422 – 29 March 1430', 62, 'https://en.wikipedia.org/wiki/Siege_of_Thessalonica_(1422%E2%80%931430)'),
  ('Q871792', 'Ottoman Greece', 'The vast majority of the territory of present-day Greece was at some point incorporated within the Ottoman Empire. The period of Ottoman rule in Greece, lasting from the mid-15th century until the successful Greek War of Independence broke out in 1821 and the First Hellenic Republic was proclaimed in 1822, is known in Greece as Turkocracy (Greek: Τουρκοκρατία, romanized: Tourkokratia, lit. ''Turkish rule'').', 1453, NULL, NULL, 1833, NULL, NULL, 'year', '1453–1833', 69, 'https://en.wikipedia.org/wiki/Ottoman_Greece'),
  ('Q701067', 'Siege of Rhodes', 'The Siege of Rhodes of 1480 was the first and failed attempt by the Ottoman Empire to seize the island stronghold of the Knights of Rhodes from Rhodes, despite about 70,000 troops, they successfully defended the island.', 1480, NULL, NULL, NULL, NULL, NULL, 'year', '1480', 58, 'https://en.wikipedia.org/wiki/Siege_of_Rhodes_(1480)'),
  ('Q2351714', 'Battle of Zonchio', 'The naval Battle of Zonchio (Turkish: Sapienza Deniz Muharebesi, also known as the Battle of Sapienza or the First Battle of Lepanto) took place on four separate days: 12, 20, 22, and 25 August 1499. It was a part of the Ottoman–Venetian War of 1499–1503.', 1499, 8, 25, NULL, NULL, NULL, 'day', '25 August 1499', 57, 'https://en.wikipedia.org/wiki/Battle_of_Zonchio'),
  ('Q767935', 'Siege of Rhodes', 'The siege of Rhodes of 1522 was the second and ultimately successful attempt by the Ottoman Empire to expel the Knights of Rhodes from their island stronghold and thereby secure Ottoman control of the Eastern Mediterranean. The first siege in 1480 had been unsuccessful.', 1522, 6, 26, 1522, 12, 22, 'day', '26 June 1522 – 22 December 1522', 68, 'https://en.wikipedia.org/wiki/Siege_of_Rhodes_(1522)'),
  ('Q1054975', 'Battle of Preveza', 'The Battle of Preveza (also known as Prevesa) was a naval engagement that occurred on 28 September 1538 near Preveza in the Ionian Sea in northwest Greece, in the same area as the Battle of Actium in 31 BC. The battle was between an Ottoman fleet, led by Kapudan Pasha Hayreddin Barbarossa, and a Holy League of Venetian and Hispano-Imperial composition, led by Genoese admiral Andrea Doria. It was part of both the Ottoman–Habsburg wars and the Ottoman Venetian War of 1537-1547.', 1538, 9, 28, NULL, NULL, NULL, 'day', '28 September 1538', 68, 'https://en.wikipedia.org/wiki/Battle_of_Preveza'),
  ('Q165425', 'Battle of Lepanto', 'The Battle of Lepanto was a naval engagement that took place on 7 October 1571 when a fleet of the Holy League, a coalition of Catholic states arranged by Pope Pius V and led by the navies of the Spanish Empire and the Republic of Venice, inflicted a major defeat on the fleet of the Ottoman Empire in the Gulf of Patras. The Ottoman forces were sailing westward from their naval station in Lepanto (the Venetian name of ancient Naupactus – Greek Ναύπακτος, Turkish İnebahtı) when they met the fleet of the Holy League which was sailing east from Messina, Sicily and used Kefalonia as its…', 1571, 10, 7, NULL, NULL, NULL, 'day', '7 October 1571', 81, 'https://en.wikipedia.org/wiki/Battle_of_Lepanto'),
  ('Q699602', 'Cretan War of 1645-1669', 'The Cretan War, also known as the War of Candia or the fifth Ottoman–Venetian war, was a conflict between the Republic of Venice and her allies (chief among them the Knights of Malta, the Papal States and France) against the Ottoman Empire and the Barbary States largely fought over the island of Crete, Venice''s largest and richest overseas possession. The war lasted from 1645 to 1669 and was fought in Crete, especially in the city of Candia, and in numerous naval engagements and raids around the Aegean Sea, with Dalmatia providing a secondary theater of operations.', 1645, 6, 23, 1669, NULL, NULL, 'day', '23 June 1645 – 1669', 68, 'https://en.wikipedia.org/wiki/Cretan_War_(1645%E2%80%931669)'),
  ('Q1144988', 'Chios massacre', 'The Chios massacre (Greek: Η σφαγή της Χίου, pronounced [i sfaˈʝi tis ˈçi.u]) was a catastrophe that resulted in the death, enslavement, and flight of about four-fifths of the total population of Greeks on the island of Chios by Ottoman troops during the Greek War of Independence in 1822. It is estimated that up to 100,000 people were killed or enslaved during the massacre, while up to 20,000 escaped as refugees.', 1822, NULL, NULL, 1822, 8, NULL, 'year', '1822', 63, 'https://en.wikipedia.org/wiki/Chios_massacre'),
  ('Q1204808', 'history of modern Greece', 'The history of modern Greece covers the history of Greece from the recognition by the Great Powers — the United Kingdom, France and Russia — of its independence from the Ottoman Empire in 1828 to the present day.', 1822, 1, 15, NULL, NULL, NULL, 'day', '15 January 1822', 57, 'https://en.wikipedia.org/wiki/History_of_modern_Greece'),
  ('Q238440', 'Battle of Navarino', 'The Battle of Navarino was a naval battle fought on 20 October (O.S. 8 October) 1827, during the Greek War of Independence (1821–1829), in Navarino Bay (modern Pylos), on the west coast of the Peloponnese peninsula, in the Ionian Sea. Allied forces from Britain, France, and Russia decisively defeated Ottoman and Egyptian forces which were trying to suppress the Greeks, thereby making Greek independence much more likely.', 1827, 10, 20, NULL, NULL, NULL, 'day', '20 October 1827', 71, 'https://en.wikipedia.org/wiki/Battle_of_Navarino'),
  ('Q657055', 'Greco-Turkish War of 1897', 'The Greco-Turkish War of 1897 or the Ottoman-Greek War of 1897 was fought between the Kingdom of Greece and the Ottoman Empire. Its immediate cause involved the ongoing Cretan Revolt and the status of the Ottoman province of Crete, whose Greek-majority population had long desired union with Greece.', 1897, NULL, NULL, 1897, 5, 20, 'year', '1897', 70, 'https://en.wikipedia.org/wiki/Greco-Turkish_War_(1897)'),
  ('Q2008840', 'Corfu incident', 'The Corfu incident was a 1923 diplomatic and military crisis between Greece and Italy. It was triggered when Enrico Tellini, an Italian general heading a commission to resolve a border dispute between Albania and Greece, was murdered in Greek territory along with two other officers of his staff.', 1923, NULL, NULL, 1923, 9, 27, 'year', '1923', 57, 'https://en.wikipedia.org/wiki/Corfu_incident'),
  ('Q153316', 'Battle of Crete', 'The Battle of Crete (German: Luftlandeschlacht um Kreta, Greek: Μάχη της Κρήτης), codenamed Operation Mercury (German: Unternehmen Merkur), was a major Axis airborne and amphibious operation during World War II to capture the island of Crete. The battle began on the morning of 20 May 1941, with multiple German airborne landings on Crete; Greek and other Allied forces, along with Cretan civilians, defended the island.', 1941, 5, 20, 1941, 6, 1, 'day', '20 May 1941 – 1 June 1941', 72, 'https://en.wikipedia.org/wiki/Battle_of_Crete'),
  ('Q544090', 'Battle of Cape Matapan', 'The Battle of Cape Matapan (Greek: Ναυμαχία του Ταινάρου) was a naval battle during the Second World War between the Allies, represented by the navies of the United Kingdom and Australia, and the Royal Italian Navy, from 27 to 29 March 1941. Cape Matapan is on the south-western coast of the Peloponnesian peninsula of Greece.', 1941, 3, 27, 1941, 3, 29, 'day', '27 March 1941 – 29 March 1941', 65, 'https://en.wikipedia.org/wiki/Battle_of_Cape_Matapan'),
  ('Q703550', 'Axis occupation of Greece', 'The occupation of Greece by the Axis powers (Greek: Η Κατοχή, romanized: I Katochi, meaning "The Occupation") began in April 1941 after the German invasion of Greece to assist its ally, Fascist Italy, in the Greco-Italian War which had begun in October 1940. Following the Battle of Crete, all of Greece was occupied by June 1941.', 1941, 4, NULL, 1944, 10, NULL, 'month', 'April 1941 – October 1944', 64, 'https://en.wikipedia.org/wiki/Axis_occupation_of_Greece'),
  ('Q2888837', 'Battle of Greece', 'The German invasion of Greece or Operation Marita (German: Unternehmen Marita), were the attacks on Greece by Italy and Germany during World War II. The Italian invasion in October 1940, which is usually known as the Greco-Italian War, was followed by the German invasion in April 1941. German landings on the island of Crete (May 1941) came after Allied forces had been defeated in mainland Greece.', 1941, 4, NULL, 1941, 4, 30, 'month', 'April 1941 – 30 April 1941', 71, 'https://en.wikipedia.org/wiki/German_invasion_of_Greece'),
  ('Q1473722', 'Dekemvriana', 'The Dekemvriana (Greek: Δεκεμβριανά, lit. ''December events'') was a series of clashes fought during World War II in Athens, Greece, from 3 December 1944 to 11 January 1945. The conflict was the culmination of months of tension between the left-wing EAM, some parts of its military arm, the ELAS, stationed in Athens, the KKE and the OPLA from one side and from the other side, the Greek Government, some parts of the Hellenic Royal Army, the Hellenic Gendarmerie, the Cities Police, the Organization X, among others and also the British Army.', 1944, 12, 3, 1945, 1, 11, 'day', '3 December 1944 – 11 January 1945', 57, 'https://en.wikipedia.org/wiki/Dekemvriana'),
  ('Q188972', 'Greek Civil War', 'The Greek Civil War took place from 1946 to 1949. The conflict, which erupted shortly after the end of World War II, consisted of a Communist-led uprising against the established government of the Kingdom of Greece.', 1946, 3, 30, 1949, 10, 16, 'day', '30 March 1946 – 16 October 1949', 76, 'https://en.wikipedia.org/wiki/Greek_Civil_War'),
  ('Q805061', 'Balkan Pact', 'The Balkan Pact (Greek: Βαλκανικό Σύμφωνο, Macedonian: Балкански пакт, Serbo-Croatian: Balkanski pakt / Балкански пакт, Slovene: Balkanski pakt, Turkish: Balkan Paktı) of 1953, officially known as the Agreement of Friendship and Cooperation, was a treaty signed by Greece, Turkey and Yugoslavia on 28 February 1953. It was signed in Ankara.', 1953, 2, 28, NULL, NULL, NULL, 'day', '28 February 1953', 61, 'https://en.wikipedia.org/wiki/Balkan_Pact_(1953)'),
  ('Q2628742', 'Athens Polytechnic uprising', 'The Athens Polytechnic uprising occurred in November 1973 as a massive student demonstration of popular rejection of the Greek military junta of 1967–1974. It began on 14 November 1973, escalated to an open anti-junta revolt, and ended in bloodshed in the early morning of 17 November after a series of events starting with a tank crashing through the gates of the Athens Polytechnic.', 1973, 11, 14, 1973, 11, 17, 'day', '14 November 1973 – 17 November 1973', 60, 'https://en.wikipedia.org/wiki/Athens_Polytechnic_uprising'),
  ('Q865513', 'Helios Airways Flight 522', 'Helios Airways Flight 522 was a scheduled international passenger flight from Larnaca, Cyprus, to Prague, Czech Republic, with a stopover in Athens, Greece, operated by a Boeing 737-300. Shortly after takeoff on 14 August 2005, Nicosia air traffic control (ATC) lost contact with the pilots operating the flight; it eventually crashed near Grammatiko, Greece.', 2005, 8, 14, NULL, NULL, NULL, 'day', '14 August 2005', 67, 'https://en.wikipedia.org/wiki/Helios_Airways_Flight_522'),
  ('Q152372', '2008 Greek riots', 'The 2008 Greek riots started on 6 December 2008, when Alexandros Grigoropoulos (Greek: Αλέξανδρος Γρηγορόπουλος), a 15-year-old Greek student, was killed by a special officer in Exarcheia district of central Athens. The killing of the young student by police resulted in large protests and demonstrations, which escalated to widespread rioting, with numerous rioters damaging property and engaging riot police with Molotov cocktails, stones and other objects.', 2008, 12, NULL, 2008, 12, 31, 'month', 'December 2008 – 31 December 2008', 67, 'https://en.wikipedia.org/wiki/2008_Greek_riots'),
  ('Q20354466', 'Greek bailout referendum, 2015', 'A referendum to decide whether Greece should accept the bailout conditions in the country''s government-debt crisis proposed jointly by the European Commission (EC), the International Monetary Fund (IMF) and the European Central Bank (ECB) on 25 June 2015 took place on 5 July 2015. The referendum was announced by Prime Minister Alexis Tsipras in the early morning of 27 June 2015 and ratified the following day by the Parliament and the President.', 2015, 7, 5, NULL, NULL, NULL, 'day', '5 July 2015', 63, 'https://en.wikipedia.org/wiki/2015_Greek_bailout_referendum'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q86458103', 'COVID-19 pandemic in Europe', 'The global COVID-19 pandemic arrived in Europe with its first confirmed case in Bordeaux, France, on 24 January 2020, and subsequently spread widely across the continent. By 17 March 2020, every country in Europe had confirmed a case, and all have reported at least one death, with the exception of Vatican City.', 2020, 1, 24, NULL, NULL, NULL, 'day', '24 January 2020', 65, 'https://en.wikipedia.org/wiki/COVID-19_pandemic_in_Europe');
